local N=ESOHardcore;local s=N.safe
local G={index=1,category=1,sort=1,cells={}};N.bagGrid=G
local cats={'All','Weapons','Armor','Consumables','Materials / other','HC Materials'}
local function label(p,x,y,w,h,size) local l=WINDOW_MANAGER:CreateControl(nil,p,CT_LABEL);l:SetAnchor(TOPLEFT,p,TOPLEFT,x,y);l:SetDimensions(w,h);l:SetFont('$(BOLD_FONT)|'..size..'|soft-shadow-thick');return l end
local function frame(p,x,y,w,h) local c=WINDOW_MANAGER:CreateControl(nil,p,CT_BACKDROP);c:SetAnchor(TOPLEFT,p,TOPLEFT,x,y);c:SetDimensions(w,h);c:SetCenterColor(.07,.08,.10,.96);c:SetEdgeTexture('',1,1,1);c:SetEdgeColor(.3,.48,.65,1);return c end
function G.build(parent) local r=WINDOW_MANAGER:CreateControl(nil,parent,CT_CONTROL);r:SetAnchorFill(parent);G.root=r;r:SetHidden(true);G.heading=label(r,28,112,900,34,20);for i=1,48 do local x=28+(i-1)%8*69;local y=156+math.floor((i-1)/8)*69;local b=frame(r,x,y,65,65);local icon=WINDOW_MANAGER:CreateControl(nil,b,CT_TEXTURE);icon:SetAnchor(TOPLEFT,b,TOPLEFT,4,4);icon:SetDimensions(57,57);local qty=label(b,5,40,60,23,17);G.cells[i]={b=b,icon=icon,qty=qty} end;G.info=label(r,595,156,325,420,22);G.bottom=label(r,28,580,900,100,20) end
local function category(e) local t=s(GetItemLinkItemType,e.link);if t==ITEMTYPE_WEAPON then return 2 elseif t==ITEMTYPE_ARMOR then return 3 elseif t==ITEMTYPE_FOOD or t==ITEMTYPE_DRINK or t==ITEMTYPE_POTION or t==ITEMTYPE_POISON then return 4 end;return 5 end
function G.render(page) if not G.root then return end;G.root:SetHidden(page~=8 and page~=9);if page~=8 and page~=9 then return end;if G.page~=page then G.index=1;G.category=1;G.page=page end;local rows={};local materialTab=page==8 and G.category==6;local source=materialTab and N.hcMaterialRows() or N.economyRows(page);for _,e in ipairs(source) do if materialTab or G.category==1 or category(e)==G.category then rows[#rows+1]=e end end;if G.sort==2 then table.sort(rows,function(a,b) if a.qty==b.qty then return a.name<b.name end;return a.qty>b.qty end) end;G.rows=rows;G.index=math.max(1,math.min(G.index,math.max(1,#rows)));local start=math.floor((G.index-1)/48)*48;local held,banked=N.hcGold();G.heading:SetText('HC gold: '..(page==9 and banked or held)..' | '..cats[G.category]..' | '..#rows..' tracked types | '..(G.sort==1 and 'Name' or 'Quantity'));local colors={{.7,.7,.7},{.9,.9,.9},{.2,.8,.3},{.25,.55,1},{.7,.35,.9},{1,.75,.2}};for i,c in ipairs(G.cells) do local e=rows[start+i];local col=e and colors[math.max(1,math.min(6,e.quality+1))] or {.2,.25,.3};c.b:SetEdgeColor(col[1],col[2],col[3],1);c.b:SetCenterColor(.07,.08,.10,1);if start+i==G.index and e then c.b:SetCenterColor(.25,.38,.52,1) end;c.icon:SetHidden(not(e and e.icon));if e and e.icon then c.icon:SetTexture(e.icon) end;c.qty:SetText(e and tostring(e.qty) or '') end;local e=rows[G.index];G.info:SetText(e and (e.name..'\n\nHC quantity: '..e.qty..'\n\n'..(materialTab and ('Craft Bag total: '..e.physical..'\nEligible quantity shown above') or (page==9 and 'Shared bank ownership' or 'Personal ownership'))) or 'No eligible items recorded.');G.bottom:SetText('X: Next category | D-pad: Select\nTracked ownership only. Native inventory / bank performs item actions.') end
function G.move(dx,dy) G.index=math.max(1,math.min(math.max(1,#(G.rows or {})),G.index+dx+dy*8)) end
function G.apply() G.category=G.category%(G.page==8 and #cats or #cats-1)+1;G.index=1 end
